package geoip

import (
	_ "embed"
	"net/netip"
	"sync"

	"github.com/echofog/echofog-core/internal/v2/geoip/internal/codec"
)

//go:generate go run gen.go -in data/dbip-country-lite.csv.gz -out country.bin

// country.bin is regenerated by go:generate from DB-IP Lite Country (CC BY 4.0); see doc.go.
//
//go:embed country.bin
var dbBytes []byte

var (
	dbOnce sync.Once
	db     *codec.DB
	dbErr  error
)

// CountryOf reports the ISO 3166-1 alpha-2 country of a public IPv4 or IPv6 address. It returns
// false for private, reserved and unknown addresses; callers treat that as a border
// (wire.md §1 point 3).
func CountryOf(a netip.Addr) (string, bool) {
	if !a.IsValid() {
		return "", false
	}
	a = a.Unmap()
	if isReserved(a) {
		return "", false
	}
	dbOnce.Do(func() { db, dbErr = codec.Decode(dbBytes) })
	if dbErr != nil {
		return "", false
	}
	return db.Lookup(a)
}

// reservedPrefixes are the IPv4 and IPv6 blocks that never name a country: private, loopback,
// link-local, multicast and the special-purpose registries (RFC 6890 and successors). The
// upstream file maps some of them to a real country (for example fe00::/9 to CH), so they must
// be rejected here rather than trusted.
var reservedPrefixes = []netip.Prefix{
	// IPv4
	netip.MustParsePrefix("0.0.0.0/8"),       // "this network"
	netip.MustParsePrefix("10.0.0.0/8"),      // private
	netip.MustParsePrefix("100.64.0.0/10"),   // shared address space (CGNAT)
	netip.MustParsePrefix("127.0.0.0/8"),     // loopback
	netip.MustParsePrefix("169.254.0.0/16"),  // link-local
	netip.MustParsePrefix("172.16.0.0/12"),   // private
	netip.MustParsePrefix("192.0.0.0/24"),    // IETF protocol assignments
	netip.MustParsePrefix("192.0.2.0/24"),    // TEST-NET-1
	netip.MustParsePrefix("192.88.99.0/24"),  // 6to4 relay anycast (deprecated)
	netip.MustParsePrefix("192.168.0.0/16"),  // private
	netip.MustParsePrefix("198.18.0.0/15"),   // benchmarking
	netip.MustParsePrefix("198.51.100.0/24"), // TEST-NET-2
	netip.MustParsePrefix("203.0.113.0/24"),  // TEST-NET-3
	netip.MustParsePrefix("224.0.0.0/4"),     // multicast
	netip.MustParsePrefix("240.0.0.0/4"),     // reserved, includes broadcast

	// IPv6
	netip.MustParsePrefix("::/96"),          // unspecified, loopback, IPv4-compatible (deprecated)
	netip.MustParsePrefix("64:ff9b::/96"),   // NAT64
	netip.MustParsePrefix("64:ff9b:1::/48"), // NAT64 local-use
	netip.MustParsePrefix("100::/64"),       // discard-only
	netip.MustParsePrefix("2001::/23"),      // IETF protocol assignments (Teredo, ORCHID, benchmarking)
	netip.MustParsePrefix("2001:db8::/32"),  // documentation
	netip.MustParsePrefix("2002::/16"),      // 6to4 (deprecated)
	netip.MustParsePrefix("3fff::/20"),      // documentation (RFC 9637)
	netip.MustParsePrefix("5f00::/16"),      // segment routing SIDs
	netip.MustParsePrefix("fc00::/7"),       // unique local (private)
	netip.MustParsePrefix("fe80::/10"),      // link-local
	netip.MustParsePrefix("fec0::/10"),      // site-local (deprecated)
	netip.MustParsePrefix("ff00::/8"),       // multicast
}

func isReserved(a netip.Addr) bool {
	for _, p := range reservedPrefixes {
		if p.Contains(a) {
			return true
		}
	}
	return false
}
